def is_prime(number: int) -> bool:
    if number <= 1:
        return False
    if number <= 3:
        return True
    for i in range(2, int(math.sqrt(number)) + 1):
        if number % i == 0:
            return False
    return True


def prime_fib(n: int) -> int:
    if n <= 0:
        raise ValueError("n should be positive")
    a, b = 1, 1
    count = 0
    while count < n:
        a, b = b, a + b
        if is_prime(a):
            count += 1
    return a


