def count_up_to(n):
    """Implement a function that takes a non-negative integer and returns an array of the first n integers that are prime numbers and less than n."""

    primes = []
    current_num = 2
    while len(primes) < n:
        if is_prime(current_num):
            primes.append(current_num)
        current_num += 1
    return primes

